create policy "Class coordinators read class results" on public.schoolpro_results for select to authenticated using(exists(select 1 from public.schoolpro_students s join public.schoolpro_classes c on c.id=s.class_id and c.school_id=s.school_id join public.schoolpro_members m on m.id=c.form_teacher_id and m.school_id=c.school_id where s.id=schoolpro_results.student_id and s.school_id=schoolpro_results.school_id and m.user_id=auth.uid() and m.role in('teacher','class_teacher'))); alter policy "Teachers read their own allocations" on public.schoolpro_subject_assignments using(not exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_subject_assignments.school_id and m.user_id=auth.uid() and m.role in('teacher','class_teacher')) or exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_subject_assignments.school_id and m.user_id=auth.uid() and (m.id=teacher_member_id or exists(select 1 from public.schoolpro_classes c where c.id=schoolpro_subject_assignments.class_id and c.school_id=m.school_id and c.form_teacher_id=m.id))));
